/**
 * Storage of customers.
 */

import { Injectable } from '@nestjs/common'
import { InjectRepository } from '@nestjs/typeorm'
import { Repository, type DeepPartial } from 'typeorm'
import { type ListQuery, type ListResult } from '../common/listing'
import { type CustomerRecord } from './customer.dto'
import { CustomerEntity } from './customer.entity'

/** Injection token of the storage of customers. */
export const CUSTOMER_REPOSITORY = Symbol('CustomerRepository')

/** Where customers are kept. The service depends only on this interface. */
export interface CustomerRepository {
  list(query: ListQuery): Promise<ListResult<CustomerRecord>>
  get(key: number): Promise<CustomerRecord | undefined>
  add(values: Omit<CustomerRecord, 'id'>): Promise<CustomerRecord>
  update(key: number, values: Partial<CustomerRecord>): Promise<CustomerRecord>
  delete(key: number): Promise<void>
}

/** A stored row as a record: empty columns become absent fields, as the API shows optional fields. */
function toRecord(row: CustomerEntity): CustomerRecord {
  return Object.fromEntries(Object.entries(row).filter(([, value]) => value !== null)) as unknown as CustomerRecord
}

/** Keeps customers in the database with TypeORM. */
@Injectable()
export class TypeOrmCustomerRepository implements CustomerRepository {
  constructor(@InjectRepository(CustomerEntity) private readonly data: Repository<CustomerEntity>) {}

  async list(query: ListQuery): Promise<ListResult<CustomerRecord>> {
    const order = query.sort ? { [query.sort.field]: query.sort.descending ? 'DESC' : 'ASC', id: 'ASC' } : { id: 'ASC' }
    const [rows, total] = await this.data.findAndCount({
      where: query.filters as never,
      order: order as never,
      skip: query.offset,
      take: query.limit,
    })
    return { items: rows.map(toRecord), total }
  }

  async get(key: number): Promise<CustomerRecord | undefined> {
    const row = await this.data.findOneBy({ id: key } as never)
    return row ? toRecord(row) : undefined
  }

  async add(values: Omit<CustomerRecord, 'id'>): Promise<CustomerRecord> {
    const row = await this.data.save(this.data.create(values as DeepPartial<CustomerEntity>))
    return (await this.get(row.id as number))!
  }

  async update(key: number, values: Partial<CustomerRecord>): Promise<CustomerRecord> {
    const row = await this.data.findOneByOrFail({ id: key } as never)
    await this.data.save(this.data.merge(row, values as DeepPartial<CustomerEntity>))
    return (await this.get(key))!
  }

  async delete(key: number): Promise<void> {
    await this.data.delete({ id: key } as never)
  }
}

