/**
 * Storage of products.
 */

import { Injectable } from '@nestjs/common'
import { InjectRepository } from '@nestjs/typeorm'
import { Repository, type DeepPartial } from 'typeorm'
import { type ListQuery, type ListResult } from '../common/listing'
import { type ProductRecord } from './product.dto'
import { ProductEntity } from './product.entity'

/** Injection token of the storage of products. */
export const PRODUCT_REPOSITORY = Symbol('ProductRepository')

/** Where products are kept. The service depends only on this interface. */
export interface ProductRepository {
  list(query: ListQuery): Promise<ListResult<ProductRecord>>
  get(key: number): Promise<ProductRecord | undefined>
  add(values: Omit<ProductRecord, 'id'>): Promise<ProductRecord>
  update(key: number, values: Partial<ProductRecord>): Promise<ProductRecord>
  delete(key: number): Promise<void>
}

/** A stored row as a record: empty columns become absent fields, as the API shows optional fields. */
function toRecord(row: ProductEntity): ProductRecord {
  return Object.fromEntries(Object.entries(row).filter(([, value]) => value !== null)) as unknown as ProductRecord
}

/** Keeps products in the database with TypeORM. */
@Injectable()
export class TypeOrmProductRepository implements ProductRepository {
  constructor(@InjectRepository(ProductEntity) private readonly data: Repository<ProductEntity>) {}

  async list(query: ListQuery): Promise<ListResult<ProductRecord>> {
    const order = query.sort ? { [query.sort.field]: query.sort.descending ? 'DESC' : 'ASC', id: 'ASC' } : { id: 'ASC' }
    const [rows, total] = await this.data.findAndCount({
      where: query.filters as never,
      order: order as never,
      skip: query.offset,
      take: query.limit,
    })
    return { items: rows.map(toRecord), total }
  }

  async get(key: number): Promise<ProductRecord | undefined> {
    const row = await this.data.findOneBy({ id: key } as never)
    return row ? toRecord(row) : undefined
  }

  async add(values: Omit<ProductRecord, 'id'>): Promise<ProductRecord> {
    const row = await this.data.save(this.data.create(values as DeepPartial<ProductEntity>))
    return (await this.get(row.id as number))!
  }

  async update(key: number, values: Partial<ProductRecord>): Promise<ProductRecord> {
    const row = await this.data.findOneByOrFail({ id: key } as never)
    await this.data.save(this.data.merge(row, values as DeepPartial<ProductEntity>))
    return (await this.get(key))!
  }

  async delete(key: number): Promise<void> {
    await this.data.delete({ id: key } as never)
  }
}

